// Shared annotated-CSV parser (adapted from wherewhen_data_restore_flow.json's
// parseFluxCsvToLines — same header-detection/multi-block logic, different
// output shape: plain row objects instead of line-protocol strings, since
// the analysis engine needs to compute with the data, not just rewrite it).
// Same known limitation carried over: naive comma-split, not RFC4180-quote-
// aware — fine given none of this project's actual field values contain a
// literal comma today (same reasoning as the restore flow's own note).
function parseFluxCsvToRows(csvText) {
    const RESERVED = new Set(['result', 'table', '_start', '_stop', '_time', '_value', '_field', '_measurement']);
    const rawLines = (csvText || '').split('\n').map(l => l.replace(/\r$/, ''));
    let header = null;
    const rows = [];

    function arraysEqual(a, b) { return a.length === b.length && a.every((v, i) => v === b[i]); }

    rawLines.forEach(raw => {
        if (raw === '') return; // blank separator between table blocks — next real row re-detects header
        if (raw.startsWith('#')) return; // #datatype/#group/#default — not needed here
        const cols = raw.split(',');
        // A header row is identified by carrying ALL THREE reserved
        // column-name markers as literal cell values (_measurement,
        // _field, _value) — not just one, and NOT "differs from the
        // previous header" (that was the original, buggy heuristic: two
        // consecutive table blocks with the same tag SET but different
        // tag VALUES produce identical header rows, which the old
        // !arraysEqual() check wrongly let fall through as a data row).
        // Real data will essentially never carry all three of those
        // exact strings as its own field/measurement/tag values.
        if (cols.includes('_measurement') && cols.includes('_field') && cols.includes('_value')) {
            header = cols;
            return;
        }
        if (!header) return; // stray row before any header seen
        if (cols.length !== header.length) return; // malformed/short row

        const row = {};
        header.forEach((colName, i) => { row[colName] = cols[i]; });

        const measurement = row['_measurement'];
        const field = row['_field'];
        const value = row['_value'];
        const time = row['_time'];
        if (!measurement || !field || value === undefined || value === '' || !time) return;

        const tags = {};
        header.forEach(colName => {
            if (!RESERVED.has(colName) && colName !== '' && row[colName] !== undefined && row[colName] !== '') {
                tags[colName] = row[colName];
            }
        });

        rows.push({ measurement, field, value, time, tags });
    });

    return rows;
}

// Fulgrim Flux Analysis Engine — analysis definitions (PLAN.md §11).
// Drafted standalone first so the JS can be brace/syntax-checked with
// Node before being embedded into Node-RED flow JSON as an escaped string.
//
// DESIGN CALL (Aug 2026, since PLAN.md left "exact Flux queries" open):
// Flux's own job here is deliberately kept to from|range|filter|pivot|sort
// — the same primitives already proven working elsewhere in this repo
// (wherewhen_data_export/restore's queries). All statistics (correlation
// coefficients, clustering counts, trend direction) are computed in plain
// JS in Node-RED after the CSV comes back, not inside Flux itself — Flux
// has covariance/stats packages that COULD do some of this, but their
// exact behavior/availability on Ward's actual InfluxDB install has never
// been confirmed, whereas a hand-written Pearson correlation in JS is
// something I can get right with high confidence without live testing.
// Matches PLAN.md's own framing: "Node-RED orchestrates... shapes results."
//
// TIER COVERAGE (Aug 2026 call, also left open by PLAN.md): rather than
// hand-assign which of the 20 analyses run at which of the 4 tiers
// (daily/weekly/monthly/all), EVERY analysis runs at EVERY tier that
// fires, just over that tier's own window/refresh cadence. Simpler, one
// code path, and "wrong" only in the sense of some extra recompute work
// on data that hasn't changed — cheap given this project's actual data
// volume (one person's health log, not fleet-scale).

// ---------- shared stats helpers ----------

function mean(arr) { return arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null; }

function pearsonCorrelation(xs, ys) {
    // xs/ys must already be the same length, same index = same day/point,
    // nulls already filtered out by the caller (alignByDay below).
    const n = xs.length;
    if (n < 3) return null; // not enough points for a meaningful coefficient
    const mx = mean(xs), my = mean(ys);
    let num = 0, dx2 = 0, dy2 = 0;
    for (let i = 0; i < n; i++) {
        const dx = xs[i] - mx, dy = ys[i] - my;
        num += dx * dy; dx2 += dx * dx; dy2 += dy * dy;
    }
    if (dx2 === 0 || dy2 === 0) return null; // no variance in one series — correlation undefined, not zero
    return num / Math.sqrt(dx2 * dy2);
}

// Simple linear trend: least-squares slope of value vs. day-index.
// Returns null if fewer than 3 points. Positive = rising, negative = falling.
function linearTrendSlope(points) { // points: [{t: dayIndexNumber, v: number}]
    const n = points.length;
    if (n < 3) return null;
    const mt = mean(points.map(p => p.t)), mv = mean(points.map(p => p.v));
    let num = 0, den = 0;
    points.forEach(p => { num += (p.t - mt) * (p.v - mv); den += (p.t - mt) * (p.t - mt); });
    return den === 0 ? null : num / den;
}

// Rows from parseFluxCsvToRows (shared parser, see analysis_engine_flow.json's
// own copy of the header-detection logic already proven in wherewhen_data_restore_flow.json)
// come back as: [{measurement, field, value, time, tags: {...}}]. Most
// analyses want one specific field per row (already field-filtered by the
// Flux query itself, via pivot() or a field filter), reduced to one
// value-per-day. dayKeyFn extracts the grouping key (usually the ISO date
// portion of `time`, but can be overridden e.g. for tag-keyed data).
// Eastern-local calendar-date key for a raw UTC timestamp -- day-
            // grouping (toDaySeries()'s default, and every direct
            // r.time-based day bucket below: incidents, medication
            // events, therapy sessions, night-waking notes) needs ONE
            // authoritative "which day" answer picked at compute time,
            // unlike clock-time DISPLAY (analysis_render.php/analysis.php
            // now do that client-side, per the viewer's own browser --
            // see the comment on bedtime_wake_time_trend's shape() for
            // why that one is different). Grouping can't be deferred to
            // display time the same way without re-deriving every trend
            // series from raw points on every page load, so this picks a
            // fixed real-world zone instead -- America/New_York, since
            // this is Ward's own single-user data. Previous behavior
            // (easternDateKey(r.time), a UTC calendar-date slice) put
            // anything after roughly 7-8pm Eastern on the NEXT UTC day --
            // e.g. a 10:35pm bedtime (2:35am UTC) was counted as
            // belonging to the following day, not the night it was
            // actually part of. Uses Intl (DST-safe) rather than a fixed
            // UTC-4/-5 offset, which would silently be wrong half the
            // year.
            // Ward, Aug 2026: "let the user set their preferred timezone" instead
            // of hardcoding one -- see settings.php / api/get_shared_config.php.
            // flow.get() rather than msg.preferred_timezone for the same
            // reason msg.secrets/period_type already go through flow context
            // in this flow (n_ae_build_flux_query/n_ae_parse_and_shape run
            // post-split, one message per analysis -- flow context is this
            // flow's established way of getting values to every one of those
            // without relying on msg surviving the split/http-request nodes
            // in between). Undefined (a fresh install that hasn't fetched
            // shared config yet, or the test flow below, which never
            // populates this) and an invalid saved zone both fall back the
            // same way get_shared_config.php's own server-side default does.
            const PREFERRED_TZ = (typeof flow !== 'undefined' && flow.get('ae_preferred_timezone')) || 'America/New_York';
            let EASTERN_DATE_FMT;
            try {
                EASTERN_DATE_FMT = new Intl.DateTimeFormat('en-CA', { timeZone: PREFERRED_TZ, year: 'numeric', month: '2-digit', day: '2-digit' });
            } catch (e) {
                node.warn('Invalid preferred_timezone "' + PREFERRED_TZ + '" -- falling back to America/New_York. ' + e.message);
                EASTERN_DATE_FMT = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' });
            }
            function easternDateKey(isoUtc) {
                return EASTERN_DATE_FMT.format(new Date(isoUtc));
            }
            function toDaySeries(rows, dayKeyFn) {
    dayKeyFn = dayKeyFn || (r => easternDateKey(r.time));
    const byDay = {};
    rows.forEach(r => {
        const day = dayKeyFn(r);
        const v = Number(r.value);
        if (!Number.isFinite(v)) return;
        // Keep the LAST value seen per day per field (matches this
        // project's existing "latest wins" convention, e.g. body comp
        // import's collapse-to-latest-per-day rule).
        byDay[day] = v;
    });
    return Object.entries(byDay).sort((a, b) => a[0] < b[0] ? -1 : 1).map(([date, value]) => ({ date, value }));
}

function boundedTrendResult(rows, min, max, label) {
    const kept = [], excluded = [];
    rows.forEach(r => {
        const v = Number(r.value);
        if (Number.isFinite(v) && v >= min && v <= max) kept.push(r);
        else excluded.push({ time: r.time, value: r.value });
    });
    const result = trendResult(toDaySeries(kept), label);
    if (excluded.length) {
        result.excluded_count = excluded.length;
        result.excluded_sample = excluded.slice(0, 5);
    }
    return result;
}

// Aligns two day-series to only the days present in BOTH — required
// before any correlation, since Pearson needs paired points.
function alignByDay(seriesA, seriesB) {
    const bByDay = {}; seriesB.forEach(p => { bByDay[p.date] = p.value; });
    const xs = [], ys = [], dates = [];
    seriesA.forEach(p => {
        if (bByDay[p.date] !== undefined) { xs.push(p.value); ys.push(bByDay[p.date]); dates.push(p.date); }
    });
    return { xs, ys, dates };
}

function trendResult(series, label) {
    const points = series.map((p, i) => ({ t: i, v: p.value }));
    return {
        series, // [{date, value}]
        count: series.length,
        average: mean(series.map(p => p.value)),
        latest: series.length ? series[series.length - 1] : null,
        trend_slope_per_day: linearTrendSlope(points),
        label,
    };
}

function correlationResult(seriesA, seriesB, labelA, labelB) {
    const { xs, ys, dates } = alignByDay(seriesA, seriesB);
    return {
        label: labelA + ' vs ' + labelB,
        paired_days: dates.length,
        correlation: pearsonCorrelation(xs, ys),
        points: dates.map((d, i) => ({ date: d, [labelA]: xs[i], [labelB]: ys[i] })),
    };
}

// ---------- Flux query builders ----------
// All take (bucket, startISO, stopISO) and return a Flux query string.
// A null/empty stopISO means "through now" (Flux's range() stop defaults
// to now() when omitted).

function fluxFieldTrend(bucket, start, stop, measurement, field, extraFilter) {
    const stopClause = stop ? ', stop: ' + stop : '';
    const filter = extraFilter ? ' and ' + extraFilter : '';
    return 'from(bucket: "' + bucket + '")\n' +
        '  |> range(start: ' + start + stopClause + ')\n' +
        '  |> filter(fn: (r) => r._measurement == "' + measurement + '" and r._field == "' + field + '"' + filter + ')\n' +
        '  |> sort(columns: ["_time"])';
}

// ---------- the 20 analyses ----------
// key: matches analysis.php's own $analyses list (godaddy/app/analysis.php)
// — MUST stay in sync with those keys, that's the join point between what
// this engine computes and what the GoDaddy chart shells expect.

const ANALYSES = {

    // ---- Automatic / measured (#1-9) ----

    sleep_duration_trend: {
        n: 1,
        flux: (b, s, e) => fluxFieldTrend(b, s, e, 'oura_sleep', 'total_sleep_duration', 'r.type == "long_sleep" or r.type == "sleep"'),
        // Defensive re-filter by field, here and in the 3 analyses below —
        // these queries ask Flux for exactly one field, but the shape
        // function doesn't just trust that blindly (a Flux query bug,
        // e.g. a wrong field name silently matching nothing plus some
        // unrelated field slipping through some other way, would
        // otherwise mix data in silently rather than erroring visibly).
        // ALSO bounded (boundedTrendResult, below) — real observed bug,
        // Aug 2026: this chart showed -1.46 to 11.77 hours, which can't be
        // right. Root cause not yet confirmed (needs real InfluxDB data —
        // wherewhen_data_export_flow.json, now fixed, dumps every raw
        // point for exactly this); this bound stops a physically-
        // impossible value from silently reaching the chart in the
        // meantime — dropped, not clamped, so a gap plus excluded_count
        // stays honest about there being a real problem, rather than
        // showing a plausible-looking but made-up number.
        shape: rows => boundedTrendResult(rows.filter(r => r.field === 'total_sleep_duration').map(r => ({ ...r, value: r.value / 3600 })), 0, 20, 'Sleep duration (hours)'),
    },
    sleep_efficiency_trend: {
        n: 2,
        flux: (b, s, e) => fluxFieldTrend(b, s, e, 'oura_sleep', 'efficiency', 'r.type == "long_sleep" or r.type == "sleep"'),
        shape: rows => boundedTrendResult(rows.filter(r => r.field === 'efficiency'), 0, 100, 'Sleep efficiency (%)'),
    },
    hrv_trend: {
        n: 3,
        flux: (b, s, e) => fluxFieldTrend(b, s, e, 'oura_sleep', 'average_hrv', 'r.type == "long_sleep" or r.type == "sleep"'),
        shape: rows => boundedTrendResult(rows.filter(r => r.field === 'average_hrv'), 0.01, 300, 'HRV (ms)'),
    },
    resting_hr_trend: {
        n: 4,
        flux: (b, s, e) => fluxFieldTrend(b, s, e, 'oura_sleep', 'lowest_heart_rate', 'r.type == "long_sleep" or r.type == "sleep"'),
        shape: rows => boundedTrendResult(rows.filter(r => r.field === 'lowest_heart_rate'), 20, 220, 'Resting heart rate (bpm)'),
    },
    body_composition_trend: {
        n: 5,
        // Multi-field: query without a single _field filter, pivot isn't
        // needed since toDaySeries only cares about one field at a time —
        // run once per tracked field, merge into one result. weight_lb
        // doubles as the headline number.
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "body_composition")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const byField = {};
            rows.forEach(r => { (byField[r.field] = byField[r.field] || []).push(r); });
            const fields = {};
            Object.keys(byField).forEach(f => { fields[f] = toDaySeries(byField[f]); });
            return {
                label: 'Body composition',
                weight_trend: fields.weight_lb ? trendResult(fields.weight_lb, 'Weight (lb)') : null,
                fields_present: Object.keys(fields),
                by_field: fields,
            };
        },
    },
    exercise_activity_trend: {
        n: 6,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "daily_log_manual" and (r._field == "steps" or r._field == "exercise_minutes" or r._field == "standing_minutes"))\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const byField = {};
            rows.forEach(r => { (byField[r.field] = byField[r.field] || []).push(r); });
            return {
                label: 'Exercise / activity',
                steps: byField.steps ? trendResult(toDaySeries(byField.steps), 'Steps') : null,
                exercise_minutes: byField.exercise_minutes ? trendResult(toDaySeries(byField.exercise_minutes), 'Exercise minutes') : null,
                standing_minutes: byField.standing_minutes ? trendResult(toDaySeries(byField.standing_minutes), 'Standing minutes') : null,
            };
        },
    },
    weight_vs_medication_cadence: {
        n: 7,
        // Pull weight (body_composition, falls back to daily_log_manual)
        // and medication start-events in the same window; shaping does
        // the day-proximity comparison, not Flux.
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => (r._measurement == "body_composition" and r._field == "weight_lb") or (r._measurement == "daily_log_manual" and r._field == "weight") or (r._measurement == "medications" and (r._field == "frequency_days")))\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const weightRows = rows.filter(r => r.field === 'weight_lb' || r.field === 'weight');
            const medRows = rows.filter(r => r.measurement === 'medications');
            const weightSeries = toDaySeries(weightRows);
            // A medication "event" is a dosage-era start — only weekly/
            // biweekly meds (frequency_days > 1) are relevant to this
            // analysis's premise (Ward's own framing: "some medications
            // are weekly/bi-weekly").
            const cadenceEvents = medRows
                .filter(r => Number(r.value) > 1)
                .map(r => ({ date: easternDateKey(r.time), medication: (r.tags && r.tags.name) || 'unknown', frequency_days: Number(r.value) }));
            // For each cadence event, weight 3 days before vs 3 days after.
            const windows = cadenceEvents.map(ev => {
                const evT = new Date(ev.date).getTime();
                const before = weightSeries.filter(p => { const d = new Date(p.date).getTime() - evT; return d >= -3 * 86400000 && d < 0; });
                const after = weightSeries.filter(p => { const d = new Date(p.date).getTime() - evT; return d >= 0 && d <= 3 * 86400000; });
                return {
                    date: ev.date, medication: ev.medication, frequency_days: ev.frequency_days,
                    weight_before_avg: mean(before.map(p => p.value)),
                    weight_after_avg: mean(after.map(p => p.value)),
                };
            });
            return { label: 'Weight vs. medication cadence', weight_trend: trendResult(weightSeries, 'Weight'), cadence_events: windows };
        },
    },
    medication_dosage_change_correlation: {
        n: 8,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "medication_dosage_history" or (r._measurement == "body_composition" and r._field == "weight_lb") or (r._measurement == "oura_sleep" and (r._field == "average_hrv" or r._field == "efficiency")) or (r._measurement == "daily_log_manual" and r._field == "mood_rating") or r._measurement == "incidents")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const changeEvents = rows.filter(r => r.measurement === 'medication_dosage_history')
                .map(r => ({ date: easternDateKey(r.time), medication: (r.tags && r.tags.medication_name) || 'unknown' }));
            const weight = toDaySeries(rows.filter(r => r.field === 'weight_lb'));
            const hrv = toDaySeries(rows.filter(r => r.field === 'average_hrv'));
            const mood = toDaySeries(rows.filter(r => r.field === 'mood_rating'));
            const incidentDays = {};
            rows.filter(r => r.measurement === 'incidents').forEach(r => { incidentDays[easternDateKey(r.time)] = (incidentDays[easternDateKey(r.time)] || 0) + 1; });
            function windowAvg(series, evT, dir) {
                const pts = series.filter(p => { const d = new Date(p.date).getTime() - evT; return dir < 0 ? (d >= -14 * 86400000 && d < 0) : (d >= 0 && d <= 14 * 86400000); });
                return mean(pts.map(p => p.value));
            }
            function windowIncidentCount(evT, dir) {
                let c = 0;
                Object.entries(incidentDays).forEach(([d, n]) => { const diff = new Date(d).getTime() - evT; if (dir < 0 ? (diff >= -14 * 86400000 && diff < 0) : (diff >= 0 && diff <= 14 * 86400000)) c += n; });
                return c;
            }
            const changes = changeEvents.map(ev => {
                const evT = new Date(ev.date).getTime();
                return {
                    date: ev.date, medication: ev.medication,
                    weight_before: windowAvg(weight, evT, -1), weight_after: windowAvg(weight, evT, 1),
                    hrv_before: windowAvg(hrv, evT, -1), hrv_after: windowAvg(hrv, evT, 1),
                    mood_before: windowAvg(mood, evT, -1), mood_after: windowAvg(mood, evT, 1),
                    incidents_before: windowIncidentCount(evT, -1), incidents_after: windowIncidentCount(evT, 1),
                };
            });
            return { label: 'Medication dosage-change correlation (14-day before/after windows)', changes };
        },
    },
    medication_adherence_vs_incidents: {
        n: 9,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => (r._measurement == "daily_log_manual" and r._field == "medications_all_taken") or r._measurement == "incidents")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const adherence = toDaySeries(rows.filter(r => r.field === 'medications_all_taken'));
            const incidentDays = {};
            rows.filter(r => r.measurement === 'incidents').forEach(r => { const d = easternDateKey(r.time); incidentDays[d] = (incidentDays[d] || 0) + 1; });
            const missedDays = adherence.filter(p => p.value === 0).map(p => p.date);
            const takenDays = adherence.filter(p => p.value === 1).map(p => p.date);
            const incidentsOnMissed = missedDays.reduce((sum, d) => sum + (incidentDays[d] || 0), 0);
            const incidentsOnTaken = takenDays.reduce((sum, d) => sum + (incidentDays[d] || 0), 0);
            return {
                label: 'Medication adherence vs. incidents',
                missed_dose_days: missedDays.length,
                full_adherence_days: takenDays.length,
                incident_rate_on_missed_days: missedDays.length ? incidentsOnMissed / missedDays.length : null,
                incident_rate_on_full_adherence_days: takenDays.length ? incidentsOnTaken / takenDays.length : null,
            };
        },
    },

    // ---- Reported (#10-16) ----

    alcohol_caffeine_vs_sleep: {
        n: 10,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => (r._measurement == "daily_log_manual" and (r._field == "alcohol_drinks" or r._field == "caffeine_servings")) or (r._measurement == "oura_sleep" and r._field == "efficiency" and (r.type == "long_sleep" or r.type == "sleep")))\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const alcohol = toDaySeries(rows.filter(r => r.field === 'alcohol_drinks'));
            const caffeine = toDaySeries(rows.filter(r => r.field === 'caffeine_servings'));
            const sleepEff = toDaySeries(rows.filter(r => r.field === 'efficiency'));
            return {
                label: 'Alcohol & caffeine vs. sleep',
                alcohol_vs_sleep_efficiency: correlationResult(alcohol, sleepEff, 'alcohol_drinks', 'sleep_efficiency'),
                caffeine_vs_sleep_efficiency: correlationResult(caffeine, sleepEff, 'caffeine_servings', 'sleep_efficiency'),
            };
        },
    },
    mood_trend_correlation: {
        n: 11,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => (r._measurement == "daily_log_manual" and (r._field == "mood_rating" or r._field == "state_of_mind" or r._field == "alcohol_drinks" or r._field == "caffeine_servings")) or (r._measurement == "oura_sleep" and r._field == "efficiency" and (r.type == "long_sleep" or r.type == "sleep")) or r._measurement == "incidents")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const mood = toDaySeries(rows.filter(r => r.field === 'mood_rating'));
            const som = toDaySeries(rows.filter(r => r.field === 'state_of_mind'));
            const sleepEff = toDaySeries(rows.filter(r => r.field === 'efficiency'));
            const alcohol = toDaySeries(rows.filter(r => r.field === 'alcohol_drinks'));
            const caffeine = toDaySeries(rows.filter(r => r.field === 'caffeine_servings'));
            const incidentDays = {};
            rows.filter(r => r.measurement === 'incidents').forEach(r => { const d = easternDateKey(r.time); incidentDays[d] = (incidentDays[d] || 0) + 1; });
            const incidentSeries = Object.entries(incidentDays).sort().map(([date, value]) => ({ date, value }));
            return {
                label: 'Mood / state-of-mind trend',
                mood_trend: trendResult(mood, 'Mood rating (0-10)'),
                state_of_mind_trend: trendResult(som, 'State of mind (1-5)'),
                mood_vs_sleep_efficiency: correlationResult(mood, sleepEff, 'mood', 'sleep_efficiency'),
                mood_vs_alcohol: correlationResult(mood, alcohol, 'mood', 'alcohol_drinks'),
                mood_vs_caffeine: correlationResult(mood, caffeine, 'mood', 'caffeine_servings'),
                mood_vs_incidents: correlationResult(mood, incidentSeries, 'mood', 'incident_count'),
            };
        },
    },
    symptom_category_clustering: {
        n: 12,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "incidents")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const byCategory = {};
            const symptomCoOccurrence = {};
            const bySleepId = {}; // group this incident's rows (one incident = one _time + several _field rows) by time
            // Defensive measurement filter — same class of gap as the
            // single-field trend analyses (see their own comments): the
            // Flux query already scopes to "incidents", but this shape
            // function groups by raw _time across whatever it's handed,
            // so trusting an unfiltered rows array would silently mix in
            // any other measurement that happened to be present.
            rows.filter(r => r.measurement === 'incidents').forEach(r => {
                const key = r.time;
                bySleepId[key] = bySleepId[key] || { category: (r.tags && r.tags.category) || 'unknown', symptoms: [] };
                const symptomFields = ['chest_sensation', 'arm_sensation', 'shoulder_sensation', 'headache_sensation', 'shaking', 'stomach_sensation', 'flu_symptoms_sensation', 'lethargy_sensation'];
                if (symptomFields.includes(r.field) && r.value && r.value !== 'none') bySleepId[key].symptoms.push(r.field);
            });
            Object.values(bySleepId).forEach(inc => {
                byCategory[inc.category] = (byCategory[inc.category] || 0) + 1;
                inc.symptoms.sort().forEach((s1, i) => inc.symptoms.slice(i + 1).forEach(s2 => {
                    const k = s1 + '+' + s2;
                    symptomCoOccurrence[k] = (symptomCoOccurrence[k] || 0) + 1;
                }));
            });
            return {
                label: 'Symptom & category clustering',
                by_category: byCategory,
                symptom_pairs: Object.entries(symptomCoOccurrence).sort((a, b) => b[1] - a[1]).map(([pair, count]) => ({ pair, count })),
                total_incidents: Object.keys(bySleepId).length,
            };
        },
    },
    incident_day_time_clustering: {
        n: 13,
        // Deliberately NOT keep()/distinct()-reduced to just _time — that
        // strips _measurement/_field/_value, which the shared CSV parser
        // (parseFluxCsvToRows) requires on every row to recognize a data
        // row at all (see its own comment). Full incident rows come
        // through instead, same query shape as symptom_category_clustering,
        // and the shape function dedupes by _time itself (needed anyway
        // since one incident has several field-rows sharing one _time).
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "incidents")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const byDow = [0, 0, 0, 0, 0, 0, 0]; // Sun..Sat
            const byHour = new Array(24).fill(0);
            const seen = new Set();
            rows.filter(r => r.measurement === 'incidents').forEach(r => {
                if (seen.has(r.time)) return; seen.add(r.time);
                const d = new Date(r.time);
                byDow[d.getDay()]++;
                byHour[d.getHours()]++;
            });
            const dowLabels = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
            return {
                label: 'Day-of-week / time-of-day incident clustering',
                by_day_of_week: dowLabels.map((label, i) => ({ label, count: byDow[i] })),
                by_hour: byHour.map((count, hour) => ({ hour, count })),
                total_incidents: seen.size,
            };
        },
    },
    incident_intensity_duration_trend: {
        n: 14,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "incidents" and (r._field == "anxiety_intensity" or r._field == "duration_minutes"))\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const intensity = rows.filter(r => r.field === 'anxiety_intensity').map(r => ({ date: r.time, value: Number(r.value) })).filter(p => Number.isFinite(p.value));
            const duration = rows.filter(r => r.field === 'duration_minutes').map(r => ({ date: r.time, value: Number(r.value) })).filter(p => Number.isFinite(p.value));
            return {
                label: 'Incident intensity/duration trend',
                intensity_trend: trendResult(intensity, 'Anxiety intensity (0-10)'),
                duration_trend: trendResult(duration, 'Duration (minutes)'),
            };
        },
    },
    therapy_session_effects: {
        n: 15,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "therapy_sessions" or r._measurement == "incidents")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const sessions = {};
            rows.filter(r => r.measurement === 'therapy_sessions').forEach(r => {
                sessions[r.time] = sessions[r.time] || { date: easternDateKey(r.time), type: (r.tags && r.tags.session_type) || 'individual' };
                if (r.field === 'mood_before') sessions[r.time].mood_before = Number(r.value);
                if (r.field === 'mood_after') sessions[r.time].mood_after = Number(r.value);
            });
            const sessionList = Object.values(sessions);
            const moodDeltas = sessionList.filter(s => s.mood_before !== undefined && s.mood_after !== undefined).map(s => s.mood_after - s.mood_before);
            const incidentDays = {};
            rows.filter(r => r.measurement === 'incidents').forEach(r => { const d = easternDateKey(r.time); incidentDays[d] = (incidentDays[d] || 0) + 1; });
            // Incident rate in the 7 days before vs after each session.
            const around = sessionList.map(s => {
                const evT = new Date(s.date).getTime();
                let before = 0, after = 0;
                Object.entries(incidentDays).forEach(([d, n]) => {
                    const diff = new Date(d).getTime() - evT;
                    if (diff >= -7 * 86400000 && diff < 0) before += n;
                    if (diff >= 0 && diff <= 7 * 86400000) after += n;
                });
                return { date: s.date, type: s.type, incidents_before_7d: before, incidents_after_7d: after };
            });
            return {
                label: 'Therapy session effects',
                session_count: sessionList.length,
                avg_mood_delta: mean(moodDeltas),
                sessions: sessionList,
                incidents_around_sessions: around,
            };
        },
    },
    night_waking_context: {
        n: 16,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "daily_log_manual" and r._field == "night_waking_notes")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            // Text field, not numeric — this analysis is a curated list,
            // not a trend/correlation. "Analysis" here means surfacing
            // the raw entries with dates, not computing a statistic —
            // matches PLAN.md #16's own framing ("capture why he woke,"
            // not a number to trend).
            const entries = rows.filter(r => r.field === 'night_waking_notes' && r.value).map(r => ({ date: easternDateKey(r.time), note: r.value }));
            return { label: 'Night-waking context', entries, count: entries.length };
        },
    },

    // ---- Headline / cross-cutting (#17-20) ----

    full_correlation_matrix: {
        n: 17,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => (r._measurement == "incidents") or (r._measurement == "daily_log_manual" and (r._field == "alcohol_drinks" or r._field == "caffeine_servings" or r._field == "weight" or r._field == "mood_rating")) or (r._measurement == "oura_sleep" and (r._field == "efficiency" or r._field == "average_hrv") and (r.type == "long_sleep" or r.type == "sleep")) or (r._measurement == "daily_log_manual" and r._field == "exercise_minutes"))\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const incidentDays = {};
            rows.filter(r => r.measurement === 'incidents').forEach(r => { const d = easternDateKey(r.time); incidentDays[d] = (incidentDays[d] || 0) + 1; });
            const series = {
                incidents: Object.entries(incidentDays).sort().map(([date, value]) => ({ date, value })),
                alcohol: toDaySeries(rows.filter(r => r.field === 'alcohol_drinks')),
                caffeine: toDaySeries(rows.filter(r => r.field === 'caffeine_servings')),
                weight: toDaySeries(rows.filter(r => r.field === 'weight')),
                mood: toDaySeries(rows.filter(r => r.field === 'mood_rating')),
                sleep_efficiency: toDaySeries(rows.filter(r => r.field === 'efficiency')),
                hrv: toDaySeries(rows.filter(r => r.field === 'average_hrv')),
                exercise_minutes: toDaySeries(rows.filter(r => r.field === 'exercise_minutes')),
            };
            const keys = Object.keys(series);
            const matrix = [];
            keys.forEach(a => keys.forEach(b2 => {
                if (a >= b2) return; // upper triangle only, avoid duplicate/self pairs
                const { xs, ys } = alignByDay(series[a], series[b2]);
                matrix.push({ a, b: b2, correlation: pearsonCorrelation(xs, ys), paired_days: xs.length });
            }));
            return { label: 'Full correlation matrix', factors: keys, matrix, note: 'Small-dataset correlations — treat as exploratory, not statistically confirmed, until data volume grows (Ward said as much when this analysis was planned, PLAN.md section 11).' };
        },
    },
    unreported_anxiety_detection: {
        n: 18,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "incidents" or (r._measurement == "oura_sleep" and (r._field == "average_hrv" or r._field == "lowest_heart_rate" or r._field == "efficiency") and (r.type == "long_sleep" or r.type == "sleep")))\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const incidentDays = new Set(rows.filter(r => r.measurement === 'incidents').map(r => easternDateKey(r.time)));
            const hrv = toDaySeries(rows.filter(r => r.field === 'average_hrv'));
            const rhr = toDaySeries(rows.filter(r => r.field === 'lowest_heart_rate'));
            const eff = toDaySeries(rows.filter(r => r.field === 'efficiency'));
            function baseline(series, onIncidentDays) {
                const vals = series.filter(p => onIncidentDays === incidentDays.has(p.date)).map(p => p.value);
                return { avg: mean(vals), n: vals.length };
            }
            const hrvIncident = baseline(hrv, true), hrvNormal = baseline(hrv, false);
            const rhrIncident = baseline(rhr, true), rhrNormal = baseline(rhr, false);
            const effIncident = baseline(eff, true), effNormal = baseline(eff, false);
            // Flag a NON-incident day as a possible unreported-anxiety day
            // if HRV is below the incident-day average AND resting HR is
            // above the incident-day average AND sleep efficiency is
            // below the incident-day average — all three, deliberately
            // conservative (fewer false positives) since this is a
            // pattern-match against a small baseline, not a diagnosis.
            const flagged = [];
            hrv.forEach(p => {
                if (incidentDays.has(p.date)) return;
                const r = rhr.find(x => x.date === p.date);
                const e = eff.find(x => x.date === p.date);
                if (!r || !e || hrvIncident.avg === null || rhrIncident.avg === null || effIncident.avg === null) return;
                if (p.value <= hrvIncident.avg && r.value >= rhrIncident.avg && e.value <= effIncident.avg) {
                    flagged.push({ date: p.date, hrv: p.value, resting_hr: r.value, sleep_efficiency: e.value });
                }
            });
            return {
                label: 'Unreported-anxiety detection',
                incident_day_baseline: { hrv: hrvIncident, resting_hr: rhrIncident, sleep_efficiency: effIncident },
                normal_day_baseline: { hrv: hrvNormal, resting_hr: rhrNormal, sleep_efficiency: effNormal },
                flagged_days: flagged,
                note: 'Pattern-match against known incident days, not a diagnosis — needs real incident history to mean anything, per PLAN.md section 11 analysis #18. Likely to want more data before trusting.',
            };
        },
    },
    bedtime_wake_time_trend: {
        n: 19,
        flux: (b, s, e) => fluxFieldTrend(b, s, e, 'oura_sleep', 'time_in_bed', 'r.type == "long_sleep" or r.type == "sleep"'),
        shape: rows => {
            // bedtime_start IS the row's own _time (that's what the sleep
            // record is timestamped at, see oura_sync_flow.json's
            // sleepRecordToLine). Wake time = bedtime + time_in_bed
            // seconds -- PLAN.md #19 flagged needing to confirm this at
            // build time; time_in_bed is the best available proxy for
            // total elapsed span without a separate bedtime_end field.
            //
            // Stores raw UTC ISO timestamps only -- no clock-hour math
            // here. An earlier version computed an hours-since-noon
            // offset in this function via Date.getHours(), which reads
            // in whatever timezone Node-RED's own container defaults to
            // (commonly UTC in a Docker add-on), not Ward's actual
            // Eastern time -- a real bug, found Aug 2026 from a live
            // chart showing a normal 10:35pm-8:50am night as if it were
            // 2:35am-12:50pm. Timezone conversion now happens exactly
            // once, explicitly, in analysis_render.php (to_eastern(),
            // fixed timezone America/New_York), instead of needing both
            // this function and the renderer to independently get it
            // right.
            const points = rows.filter(r => r.field === 'time_in_bed').map(r => {
                const bedtime = new Date(r.time);
                const wake = new Date(bedtime.getTime() + Number(r.value) * 1000);
                return { bedtime_time: bedtime.toISOString(), wake_time: wake.toISOString() };
            });
            return {
                label: 'Bedtime / wake-time trend',
                series: points,
                note: 'wake time derived from bedtime + time_in_bed, not a direct Oura bedtime_end field -- confirm against real data (PLAN.md #11 #19). bedtime_time/wake_time are raw UTC ISO timestamps; analysis_render.php converts to Eastern time for display and for grouping points into nights.',
            };
        },
    },
    sleep_stage_hypnogram: {
        n: 20,
        // Only the LONGEST night in the window is used (see shape()
        // below — picking by duration, not by which one started most
        // recently, matters here specifically) — a hypnogram is a per-
        // night chart, not a multi-night aggregate. Deliberately still
        // queries the SAME window as every
        // other analysis this run rather than a special narrower range —
        // one uniform period-window per run keeps the engine's one code
        // path simple; fetching more decomposed points than strictly
        // needed and discarding all but the latest night is wasteful but
        // cheap at this project's actual data volume.
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "oura_sleep_stage")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            // oura_sleep_stage only ever has one field ('value', see
            // decomposeSleepPhase() in oura_sync_flow.json) so this
            // filter is belt-and-suspenders rather than load-bearing —
            // consistent with the explicit field filters elsewhere in
            // this file, not strictly required by this measurement's own
            // shape the way it is for e.g. sleep_duration_trend.
            const stageRows = rows.filter(r => r.field === 'value');
            if (!stageRows.length) return { label: 'Sleep-stage timeline (hypnogram)', buckets: [], note: 'No decomposed oura_sleep_stage points in range yet.' };
            // Pick the LONGEST session (most buckets), not the one that
            // merely STARTED most recently (Ward, Aug 2026 — the old
            // "latest start time" pick was grabbing a short nap over the
            // actual previous night's sleep whenever a nap happened to
            // start later in the day than the real night began: "I go to
            // sleep one day and wake up the next," so day/start-time
            // isn't a reliable way to identify "the main night" at all —
            // duration is. A real night's sleep will always have far more
            // 15-minute buckets than a nap, so this is a robust proxy
            // without needing to cross-reference oura_sleep's own `type`
            // tag (long_sleep vs nap), which isn't carried onto these
            // decomposed oura_sleep_stage points in the first place.
            const bySleepId = {};
            stageRows.forEach(r => { (bySleepId[(r.tags && r.tags.sleep_id) || 'unknown'] = bySleepId[(r.tags && r.tags.sleep_id) || 'unknown'] || []).push(r); });
            const longestId = Object.keys(bySleepId).sort((a, b) => bySleepId[a].length - bySleepId[b].length).pop();
            const nightRows = bySleepId[longestId].sort((a, b) => a.time < b.time ? -1 : 1);
            const buckets = nightRows.map(r => ({ time: r.time, stage: (r.tags && r.tags.stage) || 'unknown' }));
            return {
                label: 'Sleep-stage timeline (hypnogram)',
                sleep_id: longestId,
                bounds: { start: buckets.length ? buckets[0].time : null, end: buckets.length ? buckets[buckets.length - 1].time : null },
                buckets,
                note: 'SLEEP_STAGE_MAP (1=deep/2=light/3=rem/4=awake) is assumed, not confirmed against real data — see the note in oura_sync_flow.json, PLAN.md section 11 analysis #20.',
            };
        },
    },
};

// ---- driver: exercises the CSV parser + all 20 shape() functions against
// embedded synthetic fixtures. Same idea as medical_history_import_test.json
// and wherewhen_data_restore_test.json — nothing on the target HA instance
// needs to exist for this to run, everything is self-contained.
const problems = [];

// ---- 1. CSV parser regression test — the exact bug found and fixed this
// session (header-detection false-negative on a repeated identical header
// row across two consecutive table blocks). ----
(function testCsvParser() {
    const csv = [
        '#datatype,string,long,dateTime:RFC3339,dateTime:RFC3339,dateTime:RFC3339,double,string,string,string,string',
        '#group,false,false,true,true,false,false,true,true,true,true',
        '#default,_result,,,,,,,,',
        ',result,table,_start,_stop,_time,_value,_field,_measurement,type,day',
        ',,0,2026-01-01T00:00:00Z,2027-01-01T00:00:00Z,2026-06-01T23:30:00Z,25200,total_sleep_duration,oura_sleep,long_sleep,2026-06-01',
        ',,0,2026-01-01T00:00:00Z,2027-01-01T00:00:00Z,2026-06-02T23:30:00Z,25300,total_sleep_duration,oura_sleep,long_sleep,2026-06-02',
        '',
        '#datatype,string,long,dateTime:RFC3339,dateTime:RFC3339,dateTime:RFC3339,double,string,string,string,string',
        '#group,false,false,true,true,false,false,true,true,true,true',
        '#default,_result,,,,,,,,',
        ',result,table,_start,_stop,_time,_value,_field,_measurement,type,day',
        ',,1,2026-01-01T00:00:00Z,2027-01-01T00:00:00Z,2026-06-01T23:30:00Z,82,efficiency,oura_sleep,long_sleep,2026-06-01',
        '',
    ].join('\n');
    const rows = parseFluxCsvToRows(csv);
    if (rows.length !== 3) {
        problems.push('CSV parser: expected 3 rows from a two-identical-header-block fixture, got ' + rows.length + ' — this is exactly the bug fixed this session (repeated header row misparsed as data). Rows: ' + JSON.stringify(rows));
    }
    const garbage = rows.find(r => r.measurement === '_measurement' || r.field === '_field');
    if (garbage) {
        problems.push('CSV parser: a header row leaked through as a data row: ' + JSON.stringify(garbage));
    }
})();

